import equinox as eqx
import jax

model = eqx.nn.MLP(in_size=4, out_size=1, width_size=32, depth=2, key=jax.random.PRNGKey(0))

@eqx.filter_jit
def loss(model, x, y):
    return ((jax.vmap(model)(x) - y) ** 2).mean()

x, y = jax.numpy.ones((8, 4)), jax.numpy.zeros((8, 1))
print(eqx.filter_grad(loss)(model, x, y).layers[0].weight.shape)
